import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useRef } from 'react';

import { XIcon, type Icon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';

const SEPARATOR_KEYS = new Set(['Enter', ',', ' ', 'Tab']);

const CHIP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.23, 1, 0.32, 1],
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9 },
  shown: { opacity: 1, scale: 1 },
};

const CHIP_FADE: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

export type ChipLook = { color: string; icon: Icon | null; hint: string };

const NEUTRAL_LOOK: ChipLook = {
  color: 'var(--muted-foreground)',
  icon: null,
  hint: '',
};

function neutralLook() {
  return NEUTRAL_LOOK;
}

function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return CHIP_FADE;
  }
  return CHIP_PRESENCE;
}

type EmailChipsFieldProps = {
  id: string;
  emails: string[];
  draft: string;
  isInvalid: boolean;
  describedBy?: string;
  onDraftChange: (draft: string) => void;
  onCommit: (text: string) => void;
  onRemove: (email: string) => void;
  /** Tints each chip by what sending will do with its address. */
  lookOf?: (email: string) => ChipLook;
};

/** Addresses become chips on Enter, comma or space; a pasted list splits into chips. */
export function EmailChipsField({
  id,
  emails,
  draft,
  isInvalid,
  describedBy,
  onDraftChange,
  onCommit,
  onRemove,
  lookOf = neutralLook,
}: EmailChipsFieldProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const chipVariants = chipVariantsOf(shouldReduceMotion);
  const hasDraft = draft.trim().length > 0;
  const lastEmail = emails.at(-1);

  function focusInput() {
    inputRef.current?.focus();
  }

  function changeDraft(event: React.ChangeEvent<HTMLInputElement>) {
    onDraftChange(event.target.value);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    const isSeparator = SEPARATOR_KEYS.has(event.key);
    const commitsDraft = isSeparator && hasDraft;
    if (commitsDraft) {
      event.preventDefault();
      onCommit(draft);
      return;
    }
    const isBackspace = event.key === 'Backspace';
    const removesLast = isBackspace && !hasDraft;
    if (removesLast && lastEmail) {
      onRemove(lastEmail);
    }
  }

  function handlePaste(event: React.ClipboardEvent<HTMLInputElement>) {
    const pasted = event.clipboardData.getData('text');
    const hasSeveral = /[\s,;]/.test(pasted.trim());
    if (hasSeveral) {
      event.preventDefault();
      onCommit(pasted);
    }
  }

  function commitOnBlur() {
    if (hasDraft) {
      onCommit(draft);
    }
  }

  return (
    <div
      onClick={focusInput}
      data-invalid={isInvalid || undefined}
      className={cn(
        CONTROL_RECIPE,
        'flex min-h-9 cursor-text flex-wrap items-center gap-1 px-1.5 py-1',
        'focus-within:border-foreground/30 focus-within:ring-ring/25 focus-within:ring-[3px]'
      )}
    >
      <AnimatePresence initial={false}>
        {emails.map((email) => {
          const look = lookOf(email);
          const ChipGlyph = look.icon;
          const hasHint = look.hint.length > 0;

          function removeEmail() {
            onRemove(email);
            focusInput();
          }

          return (
            <motion.span
              key={email}
              layout
              variants={chipVariants}
              initial='hidden'
              animate='shown'
              exit='hidden'
              transition={CHIP_TRANSITION}
              className='flex'
            >
              <Chip
                color={look.color}
                title={look.hint}
                className='h-6 max-w-56 gap-1 pr-0.5 pl-2 text-[13px]'
              >
                {ChipGlyph && <ChipGlyph strokeWidth={2.25} />}
                <span className='truncate'>{email}</span>
                {hasHint && <span className='sr-only'>{look.hint}</span>}
                <button
                  type='button'
                  aria-label={`Remove ${email}`}
                  onClick={removeEmail}
                  className='hover:bg-foreground/10 focus-visible:ring-ring/25 flex size-5 cursor-pointer items-center justify-center rounded-[5px] outline-none focus-visible:ring-[3px]'
                >
                  <XIcon className='size-3' />
                </button>
              </Chip>
            </motion.span>
          );
        })}
      </AnimatePresence>
      <input
        ref={inputRef}
        id={id}
        type='email'
        multiple
        autoComplete='off'
        value={draft}
        aria-invalid={isInvalid}
        aria-describedby={describedBy}
        placeholder='name@company.com'
        onChange={changeDraft}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
        onBlur={commitOnBlur}
        className='placeholder:text-muted-foreground/75 h-6 min-w-40 flex-1 bg-transparent px-1 text-base outline-none md:text-[13px]'
      />
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useEffectEvent, useState } from 'react';

import {
  CheckIcon,
  ClockIcon,
  LoaderCircleIcon,
  SendIcon,
  TrashIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';

import { ROLE_LABEL, type Invitation } from './data';

type ResendState = 'idle' | 'sending' | 'sent';

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

/**
 * The spring AnimatedSize resizes with. It starts from rest, so the fade leads and the freed space
 * closes after it at the pace the list follows, instead of snapping shut.
 */
const SIZE_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.32 };

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SENDING_MS = 700;

const SENT_MS = 1400;

const REVOKE_ARMED_MS = 4000;

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: { ...SIZE_SPRING, opacity: PRESENCE_OUT },
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: { ...SIZE_SPRING, opacity: PRESENCE_IN },
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

/** One card for a list of people: its ring is the only outline, and the rows are separated by space. */
export const LIST_SURFACE =
  'bg-card hairline-ring ring-border flex flex-col overflow-hidden rounded-xl py-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

function iconSwapOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE;
  }
  return ICON_SWAP;
}

function labelSwapOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE;
  }
  return LABEL_SWAP;
}

function initialOf(email: string) {
  const first = email.charAt(0);
  return first.toUpperCase();
}

function Swap({
  swapKey,
  variants,
  className,
  children,
}: {
  swapKey: string;
  variants: Variants;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span className={cn('relative inline-flex items-center', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          className='inline-flex max-w-full min-w-0 items-center whitespace-nowrap'
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

/** Someone invited who has not joined: an empty dashed slot with the first letter of the address and a clock. */
function PendingAvatar({ email }: { email: string }) {
  return (
    <span aria-hidden='true' className='relative inline-flex shrink-0'>
      <span className='hairline-border border-foreground/25 text-muted-foreground flex size-8 items-center justify-center rounded-full border-dashed text-xs font-medium'>
        {initialOf(email)}
      </span>
      <span className='bg-card absolute -right-0.5 -bottom-0.5 flex rounded-full p-px'>
        <span className='chip-3d flex size-3.5 items-center justify-center rounded-full [--chip:var(--warning)]'>
          <ClockIcon className='size-2' strokeWidth={2.75} />
        </span>
      </span>
    </span>
  );
}

function ResendGlyph({ state }: { state: ResendState }) {
  if (state === 'sending') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'sent') {
    return <CheckIcon className='text-success-foreground' />;
  }
  return <SendIcon />;
}

function ResendButton({
  email,
  onResend,
}: {
  email: string;
  onResend: () => void;
}) {
  const [state, setState] = useState<ResendState>('idle');
  const shouldReduceMotion = useReducedMotion();
  const variants = iconSwapOf(shouldReduceMotion);
  const isSending = state === 'sending';
  const deliver = useEffectEvent(onResend);

  useEffect(() => {
    if (state === 'sending') {
      const timeout = window.setTimeout(() => {
        deliver();
        setState('sent');
      }, SENDING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'sent') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, SENT_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function resend() {
    if (state !== 'idle') {
      return;
    }
    setState('sending');
  }

  return (
    <Button
      variant='ghost'
      size='icon-sm'
      aria-label={`Send the invitation to ${email} again`}
      aria-busy={isSending}
      title='Send again'
      onClick={resend}
      className='text-muted-foreground hover:text-foreground'
    >
      <Swap swapKey={state} variants={variants}>
        <ResendGlyph state={state} />
      </Swap>
    </Button>
  );
}

/** Revoking asks once more in place, in the destructive ink, and forgets the question after a few seconds. */
function RevokeButton({
  email,
  onRevoke,
}: {
  email: string;
  onRevoke: () => void;
}) {
  const [isArmed, setIsArmed] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const variants = labelSwapOf(shouldReduceMotion);
  const swapKey = String(isArmed);

  useEffect(() => {
    if (!isArmed) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsArmed(false);
    }, REVOKE_ARMED_MS);
    return () => window.clearTimeout(timeout);
  }, [isArmed]);

  function press() {
    if (isArmed) {
      onRevoke();
      return;
    }
    setIsArmed(true);
  }

  function disarm() {
    setIsArmed(false);
  }

  let accessibleLabel = `Revoke the invitation sent to ${email}`;
  if (isArmed) {
    accessibleLabel = `Confirm: revoke the invitation sent to ${email}`;
  }

  return (
    <Button
      variant='ghost'
      size='sm'
      aria-label={accessibleLabel}
      onClick={press}
      onBlur={disarm}
      className={cn(
        'text-muted-foreground hover:text-destructive-ink min-w-7 px-1.5',
        isArmed && 'bg-destructive/10 text-destructive-ink'
      )}
    >
      <AnimatedSize axis='width' as='span'>
        <Swap swapKey={swapKey} variants={variants}>
          {isArmed && 'Revoke'}
          {!isArmed && <TrashIcon />}
        </Swap>
      </AnimatedSize>
    </Button>
  );
}

function InvitationRow({
  invitation,
  isCompact,
  onResend,
  onRevoke,
}: {
  invitation: Invitation;
  isCompact: boolean;
  onResend: (invitationId: string) => void;
  onRevoke: (invitationId: string) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const lineVariants = labelSwapOf(shouldReduceMotion);
  const roleLabel = ROLE_LABEL[invitation.role];
  const line = `${roleLabel} · Invited by ${invitation.invitedBy} · ${invitation.sentLabel}`;

  function resend() {
    onResend(invitation.id);
  }

  function revoke() {
    onRevoke(invitation.id);
  }

  return (
    <div className='flex min-h-14 items-center gap-3 py-2 pr-1.5 pl-3'>
      <PendingAvatar email={invitation.email} />
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='truncate text-[13px] leading-tight font-medium'>
          {invitation.email}
        </p>
        <Swap
          swapKey={line}
          variants={lineVariants}
          className='text-muted-foreground flex min-w-0 text-xs leading-tight'
        >
          <span className='truncate'>{line}</span>
        </Swap>
      </div>
      {!isCompact && (
        <Chip color='var(--warning)' className='hidden sm:inline-flex'>
          <ClockIcon strokeWidth={2.25} />
          Pending
        </Chip>
      )}
      <div className='flex shrink-0 items-center'>
        <ResendButton email={invitation.email} onResend={resend} />
        <RevokeButton email={invitation.email} onRevoke={revoke} />
      </div>
    </div>
  );
}

type InvitationListProps = {
  invitations: Invitation[];
  isCompact?: boolean;
  onResend: (invitationId: string) => void;
  onRevoke: (invitationId: string) => void;
};

/** The pending invitations, the way the invite dialog lists them: a dashed avatar slot, the state, resend and a revoke that asks twice. */
export function InvitationList({
  invitations,
  isCompact = false,
  onResend,
  onRevoke,
}: InvitationListProps) {
  const shouldReduceMotion = useReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);

  return (
    <ul className={LIST_SURFACE}>
      <AnimatePresence initial={false}>
        {invitations.map((invitation) => (
          <motion.li
            key={invitation.id}
            variants={rowVariants}
            initial='hidden'
            animate='shown'
            exit='hidden'
          >
            <InvitationRow
              invitation={invitation}
              isCompact={isCompact}
              onResend={onResend}
              onRevoke={onRevoke}
            />
          </motion.li>
        ))}
      </AnimatePresence>
    </ul>
  );
}

